"use client";

import * as React from "react";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { cn } from "@/lib/utils";

export type GlobePin = {
  id: string;
  label: string;
  country?: string;
  x: number;
  y: number;
  value?: string;
  status?: "active" | "idle" | "warning";
  active?: boolean;
};

export type GlobeConnection = {
  from: string;
  to: string;
};

export type GlobePinsProps = {
  pins?: GlobePin[];
  connections?: GlobeConnection[];
  showTooltips?: boolean;
  showConnections?: boolean;
  autoRotate?: boolean;
  rotationSpeed?: number;
  glow?: boolean;
  variant?: "minimal" | "network" | "dashboard" | "hero";
  className?: string;
  globeClassName?: string;
  pinClassName?: string;
};

export const DEFAULT_PINS: GlobePin[] = [
  { id: "sf",        label: "San Francisco", country: "USA",     x: 14, y: 37, value: "4.2k users", status: "active",  active: true },
  { id: "london",    label: "London",        country: "UK",      x: 47, y: 29, value: "3.1k users", status: "active" },
  { id: "dubai",     label: "Dubai",         country: "UAE",     x: 60, y: 44, value: "1.8k users", status: "idle" },
  { id: "singapore", label: "Singapore",     country: "SGP",     x: 74, y: 57, value: "2.9k users", status: "active" },
  { id: "tokyo",     label: "Tokyo",         country: "Japan",   x: 82, y: 35, value: "3.7k users", status: "idle" },
  { id: "sydney",    label: "Sydney",        country: "AUS",     x: 83, y: 72, value: "1.4k users", status: "idle" },
  { id: "mumbai",    label: "Mumbai",        country: "India",   x: 64, y: 48, value: "2.2k users", status: "idle" },
  { id: "berlin",    label: "Berlin",        country: "Germany", x: 51, y: 27, value: "1.9k users", status: "active" },
];

export const DEFAULT_CONNECTIONS: GlobeConnection[] = [
  { from: "sf",        to: "london" },
  { from: "london",    to: "dubai" },
  { from: "dubai",     to: "singapore" },
  { from: "singapore", to: "tokyo" },
];

const PIN_COLOR: Record<NonNullable<GlobePin["status"]>, string> = {
  active:  "#22d3ee",
  idle:    "#475569",
  warning: "#f59e0b",
};

function pinColor(pin: GlobePin) {
  return PIN_COLOR[pin.status ?? "idle"];
}

function drawGlobe(ctx: CanvasRenderingContext2D, size: number, rotation: number) {
  const cx = size / 2;
  const cy = size / 2;
  const r  = size * 0.454;

  ctx.clearRect(0, 0, size, size);

  function dot(lat: number, lon: number) {
    const φ = (lat  * Math.PI) / 180;
    const λ = (((lon + rotation) % 360) * Math.PI) / 180;
    const cosC = Math.cos(φ) * Math.cos(λ);
    if (cosC < 0.04) return;

    const x = cx + r * Math.cos(φ) * Math.sin(λ);
    const y = cy - r * Math.sin(φ);
    const α = Math.min(1, (cosC - 0.04) / 0.3) * 0.52;

    ctx.fillStyle = `rgba(135,206,235,${α.toFixed(3)})`;
    ctx.beginPath();
    ctx.arc(x, y, 0.85, 0, Math.PI * 2);
    ctx.fill();
  }

  for (let lat = -80; lat <= 80; lat += 20) {
    for (let lon = 0; lon < 360; lon += 3) dot(lat, lon);
  }
  for (let lon = 0; lon < 360; lon += 30) {
    for (let lat = -88; lat <= 88; lat += 2.5) dot(lat, lon);
  }
}

function GlobeCanvas({ size, autoRotate, rotationSpeed }: { size: number; autoRotate: boolean; rotationSpeed: number }) {
  const canvasRef    = React.useRef<HTMLCanvasElement>(null);
  const rotRef       = React.useRef(0);
  const reduceMotion = useReducedMotion();

  React.useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || size === 0) return;

    const dpr     = Math.min(window.devicePixelRatio ?? 1, 2);
    canvas.width  = size * dpr;
    canvas.height = size * dpr;

    const ctx = canvas.getContext("2d");
    if (!ctx) return;
    ctx.scale(dpr, dpr);

    let rafId  = 0;
    let lastMs = 0;
    const dps  = 360 / rotationSpeed;

    function frame(now: number) {
      const dt = lastMs ? (now - lastMs) / 1000 : 0;
      lastMs = now;
      if (autoRotate && !reduceMotion) {
        rotRef.current = (rotRef.current + dps * dt) % 360;
      }
      drawGlobe(ctx!, size, rotRef.current);
      rafId = requestAnimationFrame(frame);
    }

    rafId = requestAnimationFrame(frame);
    return () => cancelAnimationFrame(rafId);
  }, [size, autoRotate, rotationSpeed, reduceMotion]);

  return (
    <canvas
      ref={canvasRef}
      className="absolute inset-0"
      style={{ width: size, height: size }}
      aria-hidden
    />
  );
}

function ArcConnection({ x1, y1, x2, y2, size }: { x1: number; y1: number; x2: number; y2: number; size: number }) {
  const cx   = (x1 + x2) / 2;
  const cy   = Math.min(y1, y2) - size * 0.17;
  const d    = `M ${x1.toFixed(1)} ${y1.toFixed(1)} Q ${cx.toFixed(1)} ${cy.toFixed(1)} ${x2.toFixed(1)} ${y2.toFixed(1)}`;

  const measureRef = React.useRef<SVGPathElement>(null);
  const [len, setLen] = React.useState(0);

  React.useEffect(() => {
    if (measureRef.current) setLen(measureRef.current.getTotalLength());
  }, [x1, y1, x2, y2]);

  return (
    <g>
      <path ref={measureRef} d={d} fill="none" stroke="none" />
      <path d={d} fill="none" stroke="rgba(34,211,238,0.09)" strokeWidth={1} />
      {len > 0 && (
        <motion.path
          d={d}
          fill="none"
          stroke="rgba(34,211,238,0.42)"
          strokeWidth={1.2}
          strokeLinecap="round"
          strokeDasharray={len}
          initial={{ strokeDashoffset: len, opacity: 0 }}
          animate={{ strokeDashoffset: 0, opacity: 1 }}
          transition={{ duration: 1.8, ease: "easeInOut", delay: 0.5 }}
        />
      )}
      <circle r={2.5} fill="rgba(34,211,238,0.92)" filter="url(#arc-glow)">
        <animateMotion dur="3s" repeatCount="indefinite" path={d} calcMode="linear" />
      </circle>
    </g>
  );
}

function PinMarker({
  pin, size, delay, hovered, showTooltips, onEnter, onLeave, onClick, className,
}: {
  pin: GlobePin; size: number; delay: number; hovered: boolean; showTooltips: boolean;
  onEnter: () => void; onLeave: () => void; onClick: () => void; className?: string;
}) {
  const reduceMotion = useReducedMotion();
  const color        = pinColor(pin);
  const lit          = hovered || !!pin.active;
  const dotSz        = lit ? 10 : 7;
  const px = (pin.x / 100) * size;
  const py = (pin.y / 100) * size;

  return (
    <motion.div
      className="absolute"
      style={{ left: px, top: py, transform: "translate(-50%,-50%)" }}
      initial={{ opacity: 0, scale: 0.3, y: 8 }}
      animate={{ opacity: 1, scale: 1, y: 0 }}
      transition={{ duration: 0.5, ease: [0.22, 1, 0.36, 1], delay }}
    >
      <button
        type="button"
        aria-label={`${pin.label}${pin.value ? ` — ${pin.value}` : ""}`}
        className={cn(
          "relative flex items-center justify-center rounded-full outline-none",
          "focus-visible:ring-2 focus-visible:ring-cyan-400 focus-visible:ring-offset-2 focus-visible:ring-offset-transparent",
          className,
        )}
        style={{ width: 28, height: 28 }}
        onMouseEnter={onEnter}
        onMouseLeave={onLeave}
        onFocus={onEnter}
        onBlur={onLeave}
        onClick={onClick}
      >
        {!reduceMotion && [0, 1].map((i) => (
          <motion.span
            key={i}
            className="absolute inset-0 rounded-full"
            style={{ borderWidth: 1.5, borderStyle: "solid", borderColor: color }}
            animate={{ scale: [1, 2.5], opacity: [0.5, 0] }}
            transition={{ duration: 2.2, repeat: Infinity, delay: delay + i * 1.1, ease: "easeOut" }}
          />
        ))}
        <span
          className="absolute rounded-full pointer-events-none transition-all duration-300"
          style={{ width: 22, height: 22, backgroundColor: color, opacity: lit ? 0.32 : 0.1, filter: "blur(8px)" }}
        />
        <span
          className="relative z-10 rounded-full transition-all duration-200"
          style={{ width: dotSz, height: dotSz, backgroundColor: color, boxShadow: `0 0 ${lit ? 12 : 6}px ${color}90` }}
        />
      </button>

      {showTooltips && (
        <AnimatePresence>
          {hovered && (
            <motion.div
              role="tooltip"
              className="absolute z-30 pointer-events-none"
              style={{ left: "50%", bottom: "calc(100% + 8px)", x: "-50%" }}
              initial={{ opacity: 0, y: 6, scale: 0.94 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: 4, scale: 0.94 }}
              transition={{ duration: 0.16, ease: "easeOut" }}
            >
              <div className="min-w-[112px] rounded-xl border border-white/[0.08] bg-zinc-900/96 px-3 py-2 shadow-2xl backdrop-blur-md">
                <div className="mb-0.5 flex items-center gap-1.5">
                  <span className="size-1.5 shrink-0 rounded-full" style={{ backgroundColor: color }} />
                  <p className="truncate text-[11px] font-semibold leading-tight text-white">{pin.label}</p>
                </div>
                {pin.country && <p className="pl-3 text-[10px] text-zinc-500">{pin.country}</p>}
                {pin.value && <p className="mt-0.5 pl-3 text-[10px] font-medium" style={{ color }}>{pin.value}</p>}
              </div>
              <span
                className="absolute left-1/2 top-full block -translate-x-1/2"
                style={{ borderLeft: "5px solid transparent", borderRight: "5px solid transparent", borderTop: "5px solid rgba(24,24,27,0.96)" }}
              />
            </motion.div>
          )}
        </AnimatePresence>
      )}
    </motion.div>
  );
}

export function GlobePins({
  pins            = DEFAULT_PINS,
  connections     = DEFAULT_CONNECTIONS,
  showTooltips    = true,
  showConnections = true,
  autoRotate      = true,
  rotationSpeed   = 60,
  glow            = true,
  className,
  globeClassName,
  pinClassName,
}: GlobePinsProps) {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const [size, setSize]       = React.useState(0);
  const [hovered, setHovered] = React.useState<string | null>(null);
  const [active, setActive]   = React.useState<string | null>(null);
  const reduceMotion          = useReducedMotion();

  React.useEffect(() => {
    const el = containerRef.current;
    if (!el) return;
    const ro = new ResizeObserver(([entry]) => setSize(entry.contentRect.width));
    ro.observe(el);
    setSize(el.offsetWidth);
    return () => ro.disconnect();
  }, []);

  const pinMap = React.useMemo(
    () => Object.fromEntries(pins.map((p) => [p.id, p])),
    [pins],
  );

  return (
    <div
      ref={containerRef}
      className={cn("relative aspect-square w-full select-none", className)}
      aria-label="Animated globe with location pins"
    >
      {size > 0 && (
        <>
          {glow && (
            <motion.div
              className="pointer-events-none absolute inset-[3%] rounded-full"
              style={{ background: "radial-gradient(circle, rgba(34,211,238,0.14) 0%, transparent 72%)" }}
              animate={reduceMotion ? {} : { opacity: [0.5, 0.9, 0.5], scale: [1, 1.04, 1] }}
              transition={{ duration: 10, repeat: Infinity, ease: "easeInOut" }}
            />
          )}

          <div className={cn("absolute inset-0 overflow-hidden rounded-full", globeClassName)}>
            <div
              className="absolute inset-0"
              style={{ background: "radial-gradient(circle at 37% 32%, #172234 0%, #080f1a 55%, #020810 100%)" }}
            />
            <GlobeCanvas size={size} autoRotate={autoRotate} rotationSpeed={rotationSpeed} />
            <div
              className="pointer-events-none absolute inset-0"
              style={{
                background: [
                  "radial-gradient(circle at 32% 27%, rgba(148,219,255,0.055) 0%, transparent 44%)",
                  "radial-gradient(circle at 70% 70%, rgba(0,0,0,0.5) 0%, transparent 44%)",
                  "radial-gradient(ellipse at 50% 50%, transparent 58%, rgba(0,0,0,0.78) 100%)",
                ].join(", "),
              }}
            />
            <div
              className="pointer-events-none absolute inset-0 rounded-full"
              style={{ boxShadow: "inset 0 0 70px rgba(0,0,0,0.65), inset 0 0 150px rgba(0,0,0,0.3)" }}
            />
          </div>

          {showConnections && (
            <svg
              className="pointer-events-none absolute inset-0 overflow-visible"
              width={size}
              height={size}
              viewBox={`0 0 ${size} ${size}`}
              aria-hidden
            >
              <defs>
                <filter id="arc-glow" x="-100%" y="-100%" width="300%" height="300%">
                  <feGaussianBlur stdDeviation="2.5" result="blur" />
                  <feMerge>
                    <feMergeNode in="blur" />
                    <feMergeNode in="SourceGraphic" />
                  </feMerge>
                </filter>
              </defs>
              {connections.map((c) => {
                const a = pinMap[c.from];
                const b = pinMap[c.to];
                if (!a || !b) return null;
                return (
                  <ArcConnection
                    key={`${c.from}-${c.to}`}
                    x1={(a.x / 100) * size} y1={(a.y / 100) * size}
                    x2={(b.x / 100) * size} y2={(b.y / 100) * size}
                    size={size}
                  />
                );
              })}
            </svg>
          )}

          {pins.map((pin, i) => (
            <PinMarker
              key={pin.id}
              pin={pin}
              size={size}
              delay={i * 0.09 + 0.15}
              hovered={hovered === pin.id || active === pin.id}
              showTooltips={showTooltips}
              onEnter={() => setHovered(pin.id)}
              onLeave={() => setHovered(null)}
              onClick={() => setActive(active === pin.id ? null : pin.id)}
              className={pinClassName}
            />
          ))}
        </>
      )}
    </div>
  );
}
